# mangareader — Next.js front end for the Suwayomi library on pylon.
#
# Replaces Suwayomi's stock WebUI with a fixed continuous-vertical reader,
# collapsed duplicate chapters, and on-demand AI upscaling routed through
# LocalAI's mangajanai backend (see modules/localai/backends/mangajanai).
#
# Runs on phanteks rather than beside Suwayomi on pylon: every upscale is a
# round trip to LocalAI, which is on this host, and the page cache is large
# enough that it wants the big disk here.
#
# Like localai, the source tree lives outside the flake
# (/home/noah/projects/mangareader) and is built out-of-band with
# `next build` -- this unit only runs the built server.
{
  mkSystemdService,
  pkgs,
}:
{ config, lib, ... }:
let
  cfg = config.services.mangareader;
  appDir = "/home/noah/projects/mangareader";
in
{
  options.services.mangareader = {
    enable = lib.mkEnableOption "mangareader Next.js app (user-scope)";
    port = lib.mkOption {
      type = lib.types.port;
      default = 3210;
      description = "HTTP port for the Next server.";
    };
    cacheDir = lib.mkOption {
      type = lib.types.str;
      default = "/internalmedia/mangareader";
      description = ''
        Upscale cache and SQLite index. Defaults onto the big disk: a 2x
        page is several MB and a chapter is dozens of pages, so this grows
        far past anything that belongs in a home directory.
      '';
    };
  };

  config = lib.mkIf cfg.enable (mkSystemdService {
    name = "mangareader";
    hostName = "phanteks";
    scope = "user";
    description = "Manga reader (Next.js) with AI upscaling";
    workingDirectory = appDir;
    # `next start` via the package's own entrypoint rather than the
    # node_modules/.bin shim, whose shebang points at whichever node was on
    # PATH at install time rather than the one pinned here.
    execStart = "${pkgs.nodejs_24}/bin/node ${appDir}/node_modules/next/dist/bin/next start --port ${toString cfg.port}";
    environment = {
      NODE_ENV = "production";
      PORT = toString cfg.port;
      SUWAYOMI_URL = "http://pylon:4567";
      # Same host, so stay on loopback rather than going back out over the
      # LAN to reach ourselves.
      LOCALAI_URL = "http://localhost:8090";
      CACHE_DIR = cfg.cacheDir;
    };

  const rel = cachePath(row);
  await mkdir(path.dirname(absPath(rel)), { recursive: true });
  await writeFile(absPath(rel), buffer);

  completePage(row, {
    relPath: rel,
    bytes: buffer.length,
    width,
    height,
    model,
    variant: null,
  });
}

/**
 * Drain the queue one job at a time.
 *
 * Concurrency is deliberately 1. LocalAI's Python backends run a single gRPC
 * worker, so parallel requests would queue inside LocalAI anyway -- and the
 * GPU is shared with whisper and the embedding model, so a burst here would
 * evict models something else is using.
 */
let draining: Promise<void> | null = null;

export function startDrain(): Promise<void> {
  draining ??= drainLoop().finally(() => {
    draining = null;
  });
  return draining;
}

export function isDraining(): boolean {
  return draining !== null;
}

/**
 * Sweeps over terminally-failed pages once the queue empties.
 *
 * Three attempts is right for a page someone is waiting on and wrong for a
 * multi-day bulk run: the dominant failure here is the GPU being momentarily
 * full (which surfaces as a bare 404, because LocalAI returns a URL whether
 * or not the backend wrote the file), and that clears on its own. Without
 * this, an unattended run quietly accumulates holes that only a human
 * pressing a button can fill.
 *
 * Bounded, and spaced out, so a genuinely broken page -- a source returning
 * 500 forever -- costs a few retries rather than spinning.
 */
const RETRY_SWEEPS = 3;
const SWEEP_DELAY_MS = 60_000;

async function drainLoop(): Promise<void> {
  requeueStale();
  let sweeps = 0;

  for (;;) {
    const row = claimNext();

    if (!row) {
      if (sweeps >= RETRY_SWEEPS) return;
      sweeps += 1;
      // Wait before sweeping: retrying the instant we run dry just burns the
      // remaining attempts under whatever condition caused the failure.
      await new Promise((r) => setTimeout(r, SWEEP_DELAY_MS));
      const revived = retryFailed();
      if (revived === 0) return;
      console.log(
        `[upscale] retry sweep ${sweeps}/${RETRY_SWEEPS}: requeued ${revived} failed pages`,
      );
      continue;
    }

    // Any real work resets the budget -- sweeps are for the tail of a run,
    // not a running total across one.
    sweeps = 0;

    try {
      await runJob(row);
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      console.error(
        `[upscale] chapter=${row.chapter_id} page=${row.page_index} x${row.scale}: ${message}`,
      );
      failPage(row, message);
    }
  }
}

export { CACHE_DIR };

